out2=[row[:] for row in grid]
# connect successive zero cells in every row/column, coloring only intervening cells 2
for r in range(R):
 zs=[c for c,v in enumerate(grid[r]) if v==0]
 for a,b in zip(zs,zs[1:]):
  for c in range(a+1,b): out2[r][c]=2
for c in range(C):
 zs=[r for r in range(R) if grid[r][c]==0]
 for a,b in zip(zs,zs[1:]):
  for r in range(a+1,b): out2[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out2))

out4=[row[:] for row in grid]
zero_coords=[(r,c) for r in range(R) for c in range(C) if grid[r][c]==0]
rmin=min(r for r,c in zero_coords); rmax=max(r for r,c in zero_coords)
cmin=min(c for r,c in zero_coords); cmax=max(c for r,c in zero_coords)
# 2 marks the spans across the top and bottom bounds of the zero pattern.
for r in {rmin,rmax}:
 for c in range(cmin,cmax+1):
  if grid[r][c]!=0: out4[r][c]=2
# Complete vertical tracks that contain an interior zero marker.
active_cols={c for r,c in zero_coords if rmin<r<rmax}
for c in active_cols:
 for r in range(rmin,rmax+1):
  if grid[r][c]!=0: out4[r][c]=2
print('bounds',rmin,rmax,cmin,cmax,'active vertical cols',sorted(active_cols))
print('\n'.join(' '.join(map(str,row)) for row in out4))
